import React from 'react';
import { Box, DateInput } from 'grommet';

export const DateInputBugExample = () => {
  const [value, setValue] = React.useState('2020-06-30T08:00:00.000Z');
  const onChange = (event) => {
    const nextValue = event.value;
    console.log('onChange iso date:', nextValue);
    console.log('onChange utc date:', new Date(nextValue));
    setValue(nextValue);
  };
  return (
    <Box fill align="center" justify="start" pad="large">
      <Box width="medium" gap="medium">
        <DateInput 
          format="mm/dd/yyyy" 
          value={value} 
          onChange={onChange} 
          calendarProps={{ bounds: ['2020-07-01', '2020-07-31'] }}
        />
      </Box>
    </Box>
  );
};

export default {
  title: 'Input/DateInput/DateInputBugExample',
};
